mapper.select:
SELECT sup.id, sup.code, sup.voucher_no as voucherNo, sup.create_user_id AS createUserId, sup.create_user_name AS createUserName, sup.create_time AS createTime, sup.name, sup.approve_status AS approveStatus, sup.phase, sup.grade_id AS gradeId, sup.category_id AS categoryId , sup.disabled AS disabled, sup.srm_disabled AS srmDisabled, sup.pay_method_id AS payMethodId, sup.payment_condition as paymentCondition, sup.purchase_user_id AS purchaseUserId, sup.purchase_user_name AS purchaseUserName, sup.po_follower_id as poFollowerId, sup.approve_time as approveTime, sup.identification_code as identificationCode, sup.registered_capital as registeredCapital, sup.property_json as propertyJson, sup.product_category_json as productCategoryJson, sup.application_category_json as applicationCategoryJson, sup.certificate_json as certificateJson FROM supplier sup WHERE ${params.sqlMap.default} AND sup.is_deleted=FALSE ORDER BY
${item.field} ${item.sort}
sup.create_time DESC

SELECT
  id,code,name,disabled,approve_status
FROM  supplier WHERE is_deleted=FALSE

    and approve_status = #{approveStatus}

AND category_id IN
(SELECT id FROM dict_basic WHERE is_deleted= FALSE AND type=#{type}
AND value in

    #{item}

)
ORDER BY  create_time DESC
